import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

const GEMINI_API_KEY = ""; // Kendi anahtarını ekle

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);

  // Yeni State'ler
  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);
  const [tarihceBilgisi, setTarihceBilgisi] = useState({}); // { mekanId: "tarihçe metni" }

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => { setMekanlar(data); setVeriYukleniyor(false); })
      .catch(err => { console.warn("Backend Hatası", err); setVeriYukleniyor(false); });
  }, []);

  // 🚀 HOVER ANINDA TARİHÇE ÇEKME
  const handleMouseEnter = async (m) => {
    if (m.kategori !== "Tarih") return; // Sadece tarih kategorisinde çalışsın
    if (tarihceBilgisi[m.id]) return; // Zaten çekilmişse tekrar çekme

    try {
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `${m.ad} mekanının tarihi hakkında sadece 2 cümlelik, çok çarpıcı ve profesyonel bir tarihçe bilgisi ver.`;
      const result = await model.generateContent(prompt);
      const text = result.response.text();

      setTarihceBilgisi(prev => ({ ...prev, [m.id]: text }));
    } catch (err) {
      console.error("Tarihçe alınamadı", err);
    }
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş!");
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        const { latitude, longitude } = position.coords;
        const origin = `${latitude},${longitude}`;
        const destination = encodeURIComponent(favoriler[favoriler.length - 1].ad);
        const waypoints = favoriler.slice(0, -1).map(m => encodeURIComponent(m.ad)).join('|');
        window.open(`https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}&waypoints=${waypoints}&travelmode=driving`, '_blank');
      }, () => {
        const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join('/');
        window.open(`https://www.google.com/maps/dir/${duraklar}`, '_blank');
      });
    }
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }
    setSeciliMekanId(mekan.id);
    setLoading(true);
    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `Antalya ${mekan.ad} konumundayım. Hava ${wData.sicaklik}°C. Kısa bir ipucu ver.`;
      const result = await model.generateContent(prompt);
      setAiBilgi({ cevap: result.response.text(), temp: wData.sicaklik, durum: wData.durum });
    } catch (err) { setAiBilgi({ cevap: "Hata!", temp: "--" }); } finally { setLoading(false); }
  };

  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Dalış": mekanlar.filter(m => m.kategori === "Dalış"),
    "Tekne": mekanlar.filter(m => m.kategori === "Tekne"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  const kategoriArkaPlanlari = {
    "Tarih": "https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070&auto=format&fit=crop", 
    "Doğa": "https://images.unsplash.com/photo-1433838552652-f9a46b332c40?q=80&w=2070&auto=format&fit=crop", 
    "Eğlence": "https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2070&auto=format&fit=crop", 
    "Dalış": "https://images.unsplash.com/photo-1544551763-46a013bb70d5?q=80&w=2070&auto=format&fit=crop",
    "Tekne": "https://images.unsplash.com/photo-1534008897995-27a23e859048?q=80&w=2070&auto=format&fit=crop",
    "Yemek": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1974&auto=format&fit=crop", 
  };

  if (veriYukleniyor) return <div style={{display:'flex', justifyContent:'center', alignItems:'center', height:'100vh', background:'#111827', color:'#38bdf8'}}>🌘 Yükleniyor...</div>;

  return (
    <div style={{ fontFamily: "'Poppins', sans-serif", background: '#000' }}>
      <style>{`
        html { scroll-behavior: smooth; }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 15px 40px; background: rgba(0, 0, 0, 0.9); backdrop-filter: blur(15px); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid rgba(255,255,255,0.1); }
        .nav-link { color: #cbd5e1; text-decoration: none; font-size: 13px; font-weight: 600; padding: 8px 20px; border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 50px; background: rgba(255, 255, 255, 0.05); transition: 0.3s; }
        .nav-link:hover { color: #fff; border-color: #f97316; background: rgba(249, 115, 22, 0.2); }
        .category-section { position: relative; min-height: 100vh; padding: 60px 40px; background-attachment: fixed; background-size: cover; display: flex; flex-direction: column; justify-content: center; }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.75); z-index: 1; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; position: relative; z-index: 2; }

        /* TARİHÇE OVERLAY STİLİ */
        .card { position: relative; background: rgba(30, 41, 59, 0.85); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.1); transition: 0.4s; }
        .history-overlay {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(15, 23, 42, 0.95);
            color: #f1f5f9; padding: 25px;
            display: flex; flex-direction: column; justify-content: center;
            opacity: 0; transition: opacity 0.5s ease;
            z-index: 10; pointer-events: none;
        }
        .card:hover .history-overlay { opacity: 1; }
        .btn-gradient { background: linear-gradient(135deg, #f97316 0%, #fb923c 100%); color: white; border: none; padding: 10px 25px; border-radius: 50px; font-weight: bold; cursor: pointer; }
      `}</style>

      {/* Navbar aynı kalıyor */}
      <nav className="navbar">
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
            <span style={{fontSize:'28px'}}>🏝️</span>
            <div><div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '18px' }}>ANTALYA</div><div style={{ fontWeight: 400, color: '#f97316', fontSize: '11px' }}>ROTA ASİSTANI</div></div>
        </div>
        <div style={{ display: 'flex', gap: '15px' }}>{Object.keys(kategoriler).map(kat => (<a key={kat} href={`#${kat}`} className="nav-link">{kat}</a>))}</div>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <button onClick={() => setMuzekartVar(!muzekartVar)} style={{background: muzekartVar ? '#4f46e5' : 'transparent', color:'white', border:'1px solid #4f46e5', padding:'8px 16px', borderRadius:'8px', cursor:'pointer'}}>{muzekartVar ? "💳 Müzekart Var" : "💳 Müzekart Yok"}</button>
            <div style={{fontWeight:'700', color:'#f97316'}}>{favoriler.length} Mekan</div>
            <button onClick={rotayiHaritadaGoster} className="btn-gradient">Rotayı Çiz 🚀</button>
        </div>
      </nav>

      {Object.keys(kategoriler).map((kat) => (
        <div key={kat} id={kat} className="category-section" style={{ backgroundImage: `url(${kategoriArkaPlanlari[kat]})` }}>
            <div className="overlay"></div>
            <div style={{position:'relative', zIndex: 2}}>
                <h2 style={{fontSize: '40px', color: '#f8fafc', borderLeft: '6px solid #f97316', paddingLeft: '20px', marginBottom: '30px'}}>{kat} Rotaları</h2>
                <div className="grid">
                    {kategoriler[kat].map(m => (
                        <div key={m.id} className="card" onMouseEnter={() => handleMouseEnter(m)}>
                            {/* HOVER EFEKTİ BURADA */}
                            {kat === "Tarih" && (
                              <div className="history-overlay">
                                <h4 style={{color: '#f97316', marginBottom: '10px'}}>🏛️ Tarihçe Bilgisi</h4>
                                <p style={{fontSize: '14px', lineHeight: '1.6', fontStyle: 'italic'}}>
                                  {tarihceBilgisi[m.id] || "Tarihçe yükleniyor..."}
                                </p>
                              </div>
                            )}

                            <img src={m.resim} alt={m.ad} style={{width:'100%', height:'200px', objectFit:'cover'}} />
                            <div style={{padding: '20px'}}>
                                <div style={{display:'flex', justifyContent:'space-between', marginBottom:'10px'}}>
                                    <h3 style={{margin:0, color:'#f1f5f9'}}>{m.ad}</h3>
                                    <span style={{color: '#f97316', fontWeight:'bold'}}>{(muzekartVar && kat === 'Tarih') ? "ÜCRETSİZ" : `${m.ucret} ₺`}</span>
                                </div>
                                <p style={{fontSize:'13px', color:'#94a3b8'}}>{m.aciklama}</p>
                                <div style={{ display: 'flex', gap: '10px', marginTop:'15px' }}>
                                    <button onClick={() => askSmartAI(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background:'#334155', color:'#38bdf8', cursor:'pointer', fontWeight:'bold'}}>✨ AI İpucu</button>
                                    <button onClick={() => toggleFavori(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background: favoriler.some(f=>f.id===m.id) ? '#ef4444' : '#0f766e', color:'white', cursor:'pointer', fontWeight:'bold'}}>{favoriler.some(f=>f.id===m.id) ? "Çıkar" : "Ekle +"}</button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      ))}
    </div>
  );
}

export default App;
